1	// Mục 15 của tests/bike-check.mjs (chỉ chạy với `-- --multi`): hai trang xe máy cùng phòng qua `wrangler dev` CỤC BỘ (cổng 8799, mẫu tests/multi-check.mjs Mục 7).
2	//   Không bao giờ nối Worker thật danang-sky. Tự spawn wrangler dev và luôn kill khi xong hoặc lỗi.
3	//   15a: hai trang bấm thẻ Xe máy → sảnh → tên → lái (phiên 'drive', đang lái xe máy, slot khác nhau).
4	//   15b: mỗi trang thấy người kia là XE MÁY (nhóm drive-bikes có 1 xe hiện, không có ô tô người khác trong drive-cars).
5	//   15c: lệnh vẽ của xe máy người kia ≤ 4 (đo bằng ẩn / hiện nhóm drive-bikes, hai lần render liền trong một evaluate).
6	//   15d: trang 1 nghiêng trái (lái vòng trái 10 m/s) ⇒ trang 2 thấy xe đó nghiêng cùng dấu (lean = −roll.rotation.x của nút cuộn).
7	import { fileURLToPath } from 'node:url';
8	import { spawn } from 'node:child_process';
9	import { openApp, frames } from './lib.mjs';
10	
11	const PORT = 8799, HOST = `127.0.0.1:${PORT}`;
12	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
13	
14	export async function multiSection({ browser, srv, check, info, allErrors }) {
15	  const wr = spawn(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['wrangler', 'dev', '--port', String(PORT)], { cwd: fileURLToPath(new URL('../server/multi/', import.meta.url)), shell: process.platform === 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
16	  let log = ''; wr.stdout.on('data', (d) => { log += d; }); wr.stderr.on('data', (d) => { log += d; });
17	  const stop = () => { try { if (process.platform === 'win32') spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); else wr.kill(); } catch { /* bỏ qua */ } };
18	  process.on('exit', stop);
19	  const pages = [];
20	  try {
21	    for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
22	    if (!check('15 wrangler dev cục bộ sẵn sàng (cổng 8799)', /Ready on/.test(log))) { console.log(log.slice(-2000)); return; }
23	    const URL = srv.url + '?chooser&multi=' + encodeURIComponent(`ws://${HOST}/sky`) + '&idleMs=600000';
24	    const join = async (name) => {
25	      const X = await openApp(browser, URL, { width: 480, height: 270 });
26	      X.page.setDefaultTimeout(300000);
27	      pages.push([name, X]);
28	      await X.page.waitForSelector('#chooser', { state: 'visible', timeout: 300000 });
29	      await X.page.click('#chooser [data-pick="bike"]');
30	      await X.page.waitForFunction(() => /\d/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 120000 }).catch(() => {});
31	      await X.page.fill('#exMpNameIn', name);
32	      await X.page.click('#exMpFly');
33	      await X.page.waitForFunction(() => window.__app.bike.active() && window.__app.multi.session && window.__app.multi.session.phase === 'flying', null, { timeout: 180000, polling: 500 });
34	      return X;
35	    };
36	    const X1 = await join('XeA');
37	    const X2 = await join('XeB');
38	    const me = async (X) => X.page.evaluate(() => { const s = window.__app.multi.session; return { kind: s.kind, slot: s.mySlot, bike: window.__app.bike.active(), car: window.__app.drive.active() }; });
39	    const m1 = await me(X1), m2 = await me(X2);
40	    check(`15a hai trang vào lái xe máy: A kind ${m1.kind} slot ${m1.slot}, B kind ${m2.kind} slot ${m2.slot} (khác nhau), đang lái xe máy ${m1.bike} / ${m2.bike}, không lái ô tô`,
41	      m1.kind === 'drive' && m2.kind === 'drive' && m1.slot >= 0 && m2.slot >= 0 && m1.slot !== m2.slot && m1.bike && m2.bike && !m1.car && !m2.car);
42	    /* trang 1: thay bike.update bằng bước có đầu vào cố định (giữ 10 m/s, bẻ trái hết) ⇒ nghiêng trái, gửi st = lean · 0,8 như khi lái thật */
43	    await X1.page.evaluate(() => {
44	      const B = window.__app.bike, step = B.step.bind(B), inp = { gas: 0, brake: 0, steer: 1, hard: false, grip: 1 };
45	      for (const f of window.__app.traffic.fleets()) f.mesh.visible = false;
46	      B.update = (dt) => { const s = B.state; if (!s) return; inp.gas = s.v < 8 ? 1 : 0; step(dt, inp); };
47	      B.state.v = 8;
48	    });
49	    await X2.page.evaluate(() => { const B = window.__app.bike, step = B.step.bind(B), inp = { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 }; B.update = (dt) => { if (B.state) step(dt, inp); }; });
50	    const seen = (X) => X.page.waitForFunction(() => { const g = window.__app.scene.getObjectByName('drive-bikes'); return !!g && !!g.parent && g.children.filter((o) => o.visible).length >= 1; }, null, { timeout: 180000, polling: 1000 }).catch(() => {});
51	    await Promise.all([seen(X1), seen(X2)]);
52	    await frames(X1.page, 3); await frames(X2.page, 3);
53	    const view = (X) => X.page.evaluate(() => {
54	      const A = window.__app, g = A.scene.getObjectByName('drive-bikes'), cars = A.scene.getObjectByName('drive-cars');
55	      const vis = g && g.parent ? g.children.filter((o) => o.visible) : [];
56	      const carVis = cars && cars.parent ? cars.children.filter((o) => o.name === 'drive-car' && o.visible).length : 0;
57	      let meshes = 0, lean = NaN;
58	      if (vis[0]) vis[0].traverse((o) => { if (o.isMesh && o.visible) meshes++; if (o.isMesh && o.name === 'bike-temp') lean = -o.parent.rotation.x; });
59	      /* lệnh vẽ: hai lần render liền (không khung thật xen vào), có / không nhóm xe máy người khác */
60	      let withB = NaN, without = NaN;
61	      if (g && g.parent) {
62	        const { renderer, scene, camera } = A;
63	        const r = () => { renderer.info.reset(); renderer.render(scene, camera); return renderer.info.render.calls; };
64	        r(); withB = r(); g.visible = false; without = r(); g.visible = true;
65	      }
66	      return { bikes: vis.length, carVis, meshes, lean, withB, without, myLean: A.bike.state ? A.bike.state.lean : NaN };
67	    });
68	    const v1 = await view(X1), v2 = await view(X2);
69	    info(`15 trang A: ${JSON.stringify(v1)}; trang B: ${JSON.stringify(v2)}`);
70	    check(`15b A thấy B là xe máy: ${v1.bikes} xe máy, ${v1.carVis} ô tô người khác; B thấy A là xe máy: ${v2.bikes} xe máy, ${v2.carVis} ô tô`, v1.bikes === 1 && v1.carVis === 0 && v2.bikes === 1 && v2.carVis === 0);
71	    check(`15c lệnh vẽ xe máy người khác (camera có thể không nhìn thấy xe: đếm cả lưới hiện): A ${v1.withB - v1.without} lệnh vẽ / ${v1.meshes} lưới, B ${v2.withB - v2.without} lệnh vẽ / ${v2.meshes} lưới (≤ 4)`,
72	      v1.withB - v1.without <= 4 && v2.withB - v2.without <= 4 && v1.meshes <= 4 && v2.meshes <= 4 && v1.meshes >= 1);
73	    /* chờ trang B nhận vài mẫu sau khi A đã nghiêng */
74	    await sleep(4000); await frames(X2.page, 3);
75	    const a = await X1.page.evaluate(() => window.__app.bike.state.lean);
76	    const b = (await view(X2)).lean;
77	    check(`15d dấu nghiêng: A tự nghiêng ${a.toFixed(3)} rad (trái +), B thấy xe A nghiêng ${Number(b).toFixed(3)} rad, cùng dấu`, a > 0.05 && b > 0.02 && Math.sign(a) === Math.sign(b));
78	  } finally {
79	    for (const [name, X] of pages) { allErrors.push(['15 ' + name, X.errors]); try { await X.page.close(); } catch { /* bỏ qua */ } }
80	    stop();
81	    await sleep(1500);
82	  }
83	}
