1	/* ===== Trò chuyện theo khoảng cách (D-041): nút 💬, bảng tin, phím, đồng hồ danh sách gần =====
2	   Phần DOM của chat; sổ tin và quy tắc gần ở chatCore.ts, bong bóng trên đầu ở labels.ts (exLabelsSay). index.ts gọi attach / sync / detach / setSelf.
3	   - body.ex-chat: phiên từng có chatOk (máy chủ biết chat) và đang giữ chỗ / đang xem / vừa mất kết nối; CSS chỉ hiện nút khi body.explore.ex-chat.
4	   - Danh sách gần: setInterval(nearTickMs) từ attach tới detach, ngoài vòng vẽ; chỉ ghi DOM khi khóa danh sách đổi. Vòng vẽ chỉ gọi setSelf (5 lần/s, không cấp phát).
5	   - Mỗi tin một nút DOM, không dựng lại cả danh sách; quá historyMax thì gỡ nút cũ nhất. Mọi chữ từ mạng ghi bằng textContent.
6	   - Trình nghe gắn một lần lúc nạp module trên phần tử cố định (index.html), không gắn / gỡ theo lần mở bảng. */
7	import { CONFIG } from '../../config';
8	import { t, onChange as onLang } from '../../i18n';
9	import { exSanitizeChat } from './protocol';
10	import { ChLog, chKey, chNear, type ChMsg, type ChPeer } from './chatCore';
11	import { exRemotes } from './remote';
12	import { stAvatars } from '../stroll/avatars';
13	import { exDrivers } from './remoteDrive';
14	import { exLabelsSay } from './labels';
15	import type { MultiSession } from './session';
16	
17	const M = CONFIG.explore.multi, C = M.chat, NW = M.stroll.slots, ND = M.drive.slots;
18	const log = new ChLog(C.historyMax, C.ackMs, C.ratePerWin, C.rateWinMs);   // giờ trong sổ là Date.now() (cùng đồng hồ cho hạn hồi âm, hạn mức và giờ HH:MM)
19	interface Els { btn: HTMLButtonElement; near: HTMLElement; dot: HTMLElement; panel: HTMLElement; status: HTMLElement; list: HTMLElement; form: HTMLFormElement; input: HTMLTextAreaElement; send: HTMLButtonElement }
20	let el: Els | null = null;
21	const rows = new Map<number, { row: HTMLElement; st: HTMLElement | null }>();   // khóa tin → nút DOM của tin + dòng trạng thái (chỉ tin mình)
22	let session: MultiSession | null = null;
23	let had = false;          // phiên này từng có chatOk (mất kết nối thì chatOk về false nhưng vẫn hiện để thấy trạng thái)
24	let avail = false;        // body.ex-chat đang bật
25	let opened = false;       // bảng đang mở
26	let locked = true;        // khóa gửi (không ai ở gần / đang xem / mất kết nối)
27	let timer = 0;            // setInterval nearTickMs
28	let self: { x: number; y: number; z: number } | null = null;   // vị trí mình vừa gửi lên máy chủ (đúng cái máy chủ biết)
29	let prev: Set<string> = new Set();   // khóa người ở gần lần trước (trễ hai ngưỡng)
30	let near: ChPeer[] = [];
31	let nearKey = '';         // khóa + tên danh sách gần đang vẽ ('' = rỗng)
32	
33	const ERR = new Set(['fail', 'rate', 'bad']);
34	const two = (v: number) => (v < 10 ? '0' : '') + v;
35	const hhmm = (ms: number) => { const d = new Date(ms); return two(d.getHours()) + ':' + two(d.getMinutes()); };
36	
37	/* Chữ dòng trạng thái của tin mình */
38	function stText(m: ChMsg): string {
39	  switch (m.state) {
40	    case 'pending': return t('chatSending');
41	    case 'ok': return '✓';
42	    case 'alone': return t('chatAlone');
43	    case 'rate': return t('chatRate');
44	    case 'bad': return t('chatBad');
45	    default: return t('chatFail');
46	  }
47	}
48	
49	/* Ghi lại đúng dòng trạng thái của một tin mình */
50	function paintState(m: ChMsg): void {
51	  const r = rows.get(m.key);
52	  if (!r || !r.st) return;
53	  r.st.textContent = stText(m);
54	  r.st.title = m.state === 'ok' ? t('chatSent', { n: m.n }) : '';
55	  r.st.className = 'ex-chat-st' + (ERR.has(m.state) ? ' err' : '');
56	}
57	
58	/* Thêm một tin vào cuối bảng: dòng đầu (chấm màu slot, tên, giờ), thân chữ, và dòng trạng thái với tin mình. Đang ở gần cuối hoặc tin mình thì cuộn xuống cuối */
59	function addRow(m: ChMsg): void {
60	  if (!el) return;
61	  const L = el.list, stick = m.mine || L.scrollHeight - L.scrollTop - L.clientHeight < 40;
62	  const slot = m.mine ? (session ? session.mySlot : -1) : m.slot, name = m.mine ? (session ? session.name : '') : m.name;
63	  const row = document.createElement('div'); row.className = 'ex-chat-msg' + (m.mine ? ' me' : '');
64	  const head = document.createElement('div'); head.className = 'ex-chat-head';
65	  const dot = document.createElement('i'); dot.style.background = slot >= 0 ? M.colors[slot % M.colors.length] : 'var(--gold)';
66	  const nm = document.createElement('b'); nm.dir = 'auto'; nm.textContent = name;
67	  const tm = document.createElement('span'); tm.textContent = hhmm(m.at);
68	  head.append(dot, nm, tm);
69	  const body = document.createElement('div'); body.className = 'ex-chat-body'; body.dir = 'auto'; body.textContent = m.text;
70	  row.append(head, body);
71	  let st: HTMLElement | null = null;
72	  if (m.mine) { st = document.createElement('div'); row.appendChild(st); }
73	  rows.set(m.key, { row, st });
74	  L.appendChild(row);
75	  if (m.mine) paintState(m);
76	  for (const g of log.trim()) { const r = rows.get(g.key); if (r) { r.row.remove(); rows.delete(g.key); } }
77	  if (stick) L.scrollTop = L.scrollHeight;
78	}
79	
80	/* Chấm đỏ chưa đọc: chỉ khi bảng đóng */
81	function paintDot(): void { if (el) el.dot.hidden = opened || log.unread === 0; }
82	
83	/* Nút gửi khóa khi khóa gửi hoặc ô rỗng */
84	function paintSend(): void { if (el) el.send.disabled = locked || el.input.value.trim() === ''; }
85	
86	/* Dòng trạng thái + khóa gửi theo pha và danh sách gần */
87	function paintStatus(): void {
88	  if (!el) return;
89	  const ph = session ? session.phase : 'solo';
90	  let txt: string, lock = true;
91	  if (ph === 'flying') {
92	    if (near.length === 0) txt = t('chatNone');
93	    else { lock = false; txt = near.length === 1 ? t('chatOne', { name: '⁨' + near[0].name + '⁩' }) : t('chatMany', { n: near.length }); }   // tên bọc cô lập hướng chữ
94	  } else txt = t(ph === 'watching' ? 'chatWatch' : 'chatLost');
95	  if (el.status.textContent !== txt) el.status.textContent = txt;
96	  if (lock !== locked) { locked = lock; el.input.disabled = lock; }
97	  paintSend();
98	}
99	
100	/* Huy hiệu số người ở gần + dòng trạng thái */
101	function paintNear(): void {
102	  if (!el) return;
103	  el.near.hidden = near.length === 0;
104	  el.near.textContent = near.length ? String(near.length) : '';
105	  paintStatus();
106	}
107	
108	/* Nút nháy một lần khi có người mới vào tầm (gỡ lớp ở animationend; đang nháy thì chạy lại từ đầu) */
109	function pulse(): void {
110	  if (!el) return;
111	  const b = el.btn;
112	  if (b.classList.contains('pulse')) { b.classList.remove('pulse'); void b.offsetWidth; }
113	  b.classList.add('pulse');
114	}
115	
116	/* Người khác cùng phòng có trạng thái (bỏ mình và người chưa có mẫu) */
117	function peers(s: MultiSession): ChPeer[] {
118	  const out: ChPeer[] = [];
119	  for (let i = 0; i < M.slots; i++) {
120	    if (s.kind === 'fly' && i === s.mySlot) continue;
121	    const st = exRemotes.slotState(i), nm = exRemotes.name(i);
122	    if (st && nm !== null) out.push({ k: 'fly', slot: i, name: nm, x: st.pos.x, y: st.pos.y, z: st.pos.z });
123	  }
124	  for (let i = 0; i < NW; i++) {
125	    if (i === stAvatars.self || (s.kind === 'walk' && i === s.mySlot)) continue;
126	    const st = stAvatars.slotState(i), nm = stAvatars.name(i);
127	    if (st && nm !== null) out.push({ k: 'walk', slot: i, name: nm, x: st.x, y: st.y, z: st.z });
128	  }
129	  for (let i = 0; i < ND; i++) {
130	    if (s.kind === 'drive' && i === s.mySlot) continue;
131	    const st = exDrivers.slotState(i), nm = exDrivers.name(i);
132	    if (st && nm !== null) out.push({ k: 'drive', slot: i, name: nm, x: st.x, y: st.y, z: st.z });
133	  }
134	  return out;
135	}
136	
137	/* Đồng hồ nearTickMs: tin chờ quá hạn thành "Chưa gửi được"; tính lại danh sách gần (chỉ khi đang giữ chỗ), ghi DOM khi khóa đổi */
138	function tick(): void {
139	  const s = session;
140	  if (!s || !avail) return;
141	  for (const m of log.expire(Date.now())) paintState(m);
142	  if (s.phase !== 'flying') return;
143	  near = chNear(self, peers(s), prev, C.nearIn, C.radius);
144	  const key = near.map(p => chKey(p.k, p.slot) + '=' + p.name).join('|');
145	  if (key === nearKey) return;
146	  nearKey = key;
147	  const next = new Set<string>();
148	  let fresh = false;
149	  for (const p of near) { const k = chKey(p.k, p.slot); next.add(k); if (!prev.has(k)) fresh = true; }
150	  prev = next;
151	  if (fresh) pulse();
152	  paintNear();
153	}
154	
155	/* Quên danh sách gần (không giữ chỗ / rời phiên) */
156	function dropNear(): void { self = null; prev = new Set(); near = []; nearKey = ''; paintNear(); }
157	
158	/* Gửi chữ trong ô: rỗng sau khi làm sạch thì thôi; quá hạn mức thì hiện tin "gửi nhanh quá" mà không gửi; transport không nhận thì "Chưa gửi được" ngay */
159	function send(): void {
160	  if (!el || !session || locked) return;
161	  const text = exSanitizeChat(el.input.value);
162	  if (text === null) return;
163	  const now = Date.now();
164	  const m = log.canSend(now) ? log.addMine(text, now) : log.addMine(text, now, true);
165	  if (m.state === 'pending' && !session.sendChat(text, m.id)) m.state = 'fail';
166	  addRow(m);
167	  el.input.value = ''; fit(); paintSend();
168	  el.input.focus();
169	}
170	
171	/* Ô nhập tự cao theo nội dung (CSS max-height giữ ≤ 4 dòng) */
172	function fit(): void {
173	  if (!el) return;
174	  const i = el.input;
175	  i.style.height = 'auto';
176	  i.style.height = (i.scrollHeight + 2) + 'px';   // + viền trên dưới (box-sizing border-box)
177	}
178	
179	export const exChat = {
180	  onActivity: (() => {}) as () => void,   // index.ts gán = () => exMulti.activity(): gõ trong ô chat tính là còn đó
181	
182	  /* Gắn phiên mới: móc onChat / onChatAck, bật đồng hồ nearTickMs */
183	  attach(s: MultiSession): void {
184	    exChat.detach();
185	    session = s;
186	    s.onChat = (c) => {
187	      if (s !== session) return;
188	      const text = exSanitizeChat(c.text);   // máy chủ đã làm sạch; làm lại để máy chủ lạ không chèn ký tự điều khiển / bidi
189	      if (text === null) return;
190	      addRow(log.addTheirs(c.k, c.slot, c.name, text, Date.now(), opened));
191	      exLabelsSay(c.k, c.slot, text, performance.now());
192	      paintDot();
193	    };
194	    s.onChatAck = (a) => { if (s !== session) return; const m = log.ack(a.id, a.n, a.why); if (m) paintState(m); };
195	    timer = window.setInterval(tick, C.nearTickMs);
196	  },
197	
198	  /* Gọi trong s.onChange: hiện / ẩn, dòng trạng thái; mất kết nối thì mọi tin đang chờ thành "Chưa gửi được" */
199	  sync(s: MultiSession): void {
200	    if (s !== session) return;
201	    if (s.chatOk) had = true;
202	    const on = had && (s.phase === 'flying' || s.phase === 'watching' || (s.phase === 'solo' && s.notice === 'lost'));
203	    if (on !== avail) { avail = on; document.body.classList.toggle('ex-chat', on); if (!on) exChat.close(); }
204	    if (s.phase === 'solo') for (const m of log.failAll()) paintState(m);
205	    if (s.phase !== 'flying') dropNear(); else paintStatus();
206	  },
207	
208	  /* exMulti.end(): dừng đồng hồ, xóa sổ + DOM, đóng bảng, bỏ lớp body */
209	  detach(): void {
210	    clearInterval(timer); timer = 0;
211	    if (session) { session.onChat = () => {}; session.onChatAck = () => {}; }
212	    session = null; had = false;
213	    log.clear(); rows.clear();
214	    if (el) el.list.textContent = '';
215	    exChat.close();
216	    avail = false; document.body.classList.remove('ex-chat');
217	    dropNear(); paintDot();
218	  },
219	
220	  /* Vị trí mình vừa gửi lên máy chủ (index.ts, ≤ sendHz lần/s); không cấp phát */
221	  setSelf(x: number, y: number, z: number): void {
222	    if (self) { self.x = x; self.y = y; self.z = z; } else self = { x, y, z };
223	  },
224	
225	  open(): void {
226	    if (!el || !avail) return;
227	    if (!opened) { opened = true; el.panel.hidden = false; el.btn.setAttribute('aria-expanded', 'true'); }
228	    log.read(); paintDot();
229	    el.list.scrollTop = el.list.scrollHeight;
230	  },
231	
232	  /* Đóng bảng; luôn bỏ focus ô nhập (không thì WASD vẫn bị isField nuốt) */
233	  close(): void {
234	    if (!el) return;
235	    if (document.activeElement === el.input) el.input.blur();
236	    if (!opened) return;
237	    opened = false; el.panel.hidden = true; el.btn.setAttribute('aria-expanded', 'false');
238	    paintDot();
239	  },
240	
241	  get isOpen(): boolean { return opened; },
242	
243	  /* Cho test (?test): trạng thái giao diện chat */
244	  debug(): { available: boolean; open: boolean; near: string[]; unread: number; count: number; status: string; canSend: boolean; self: { x: number; y: number; z: number } | null } {
245	    return { available: avail, open: opened, near: near.map(p => p.name), unread: log.unread, count: log.list.length, status: el ? el.status.textContent : '', canSend: !locked, self: self ? { ...self } : null };
246	  }
247	};
248	
249	/* ===== Gắn trình nghe một lần (phần tử cố định trong index.html) ===== */
250	function bind(): void {
251	  const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T | null;
252	  const btn = $<HTMLButtonElement>('exChatBtn'), panel = $('exChat'), input = $<HTMLTextAreaElement>('exChatIn'), form = $<HTMLFormElement>('exChatForm');
253	  if (!btn || !panel || !input || !form) return;
254	  el = { btn, near: $('exChatNear')!, dot: $('exChatDot')!, panel, status: $('exChatStatus')!, list: $('exChatList')!, form, input, send: $<HTMLButtonElement>('exChatSend')! };
255	  input.placeholder = t('chatPlaceholder');
256	  input.disabled = true;
257	  btn.addEventListener('click', () => {
258	    if (opened) { exChat.close(); return; }
259	    exChat.open();
260	    if (!locked && window.matchMedia?.('(hover: hover)').matches) input.focus();   // máy cảm ứng: không tự bật bàn phím ảo che màn hình
261	  });
262	  btn.addEventListener('animationend', () => btn.classList.remove('pulse'));
263	  form.addEventListener('submit', (e) => { e.preventDefault(); send(); });
264	  input.addEventListener('input', () => { fit(); paintSend(); });
265	  input.addEventListener('keydown', (e) => {
266	    exChat.onActivity();
267	    if (e.key === 'Escape') { e.stopPropagation(); e.preventDefault(); exChat.close(); return; }   // chỉ đóng bảng: không nổi bọt tới window (explore/index.ts thoát chế độ)
268	    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing && e.keyCode !== 229) { e.preventDefault(); send(); }   // Shift + Enter xuống dòng; đang gõ bộ gõ (IME) thì không gửi
269	  });
270	  /* Enter ngoài ô nhập / nút: mở bảng và đưa focus vào ô */
271	  window.addEventListener('keydown', (e) => {
272	    if (e.key !== 'Enter' || e.shiftKey || e.ctrlKey || e.metaKey || e.altKey || e.isComposing) return;
273	    const tg = e.target as HTMLElement | null;
274	    if (tg && /^(INPUT|TEXTAREA|SELECT|BUTTON)$/.test(tg.tagName)) return;
275	    const b = document.body.classList;
276	    if (!b.contains('explore') || !b.contains('ex-chat')) return;
277	    e.preventDefault();
278	    exChat.open();
279	    if (!locked) input.focus();
280	  });
281	  onLang(() => {
282	    input.placeholder = t('chatPlaceholder');
283	    paintStatus();
284	    for (const m of log.list) if (m.mine) paintState(m);
285	  });
286	}
287	if (typeof document !== 'undefined') bind();
288

